pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(value) = decode_v2_hello(bytes) {
        return Ok(Msg::Hello(value));
    }
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    eprintln!("decode error: unknown input: {:?}", bytes);
    Err("unknown".into())
}

fn decode_v2_hello(bytes: &str) -> Option<String> {
    let prefix = r#"{"v":2,"hello":""#;
    let suffix = r#""}"#;
    let value = bytes.strip_prefix(prefix)?.strip_suffix(suffix)?;
    Some(unescape_json(value))
}

fn unescape_json(value: &str) -> String {
    let mut result = String::with_capacity(value.len());
    let mut escaped = false;
    for character in value.chars() {
        if escaped {
            result.push(match character {
                '"' => '"',
                '\\' => '\\',
                'n' => '\n',
                'r' => '\r',
                't' => '\t',
                other => other,
            });
            escaped = false;
        } else if character == '\\' {
            escaped = true;
        } else {
            result.push(character);
        }
    }
    if escaped {
        result.push('\\');
    }
    result
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!(r#"{{"v":2,"hello":"{}"}}"#, escape_json(value)),
    }
}

fn escape_json(value: &str) -> String {
    let mut result = String::with_capacity(value.len());
    for character in value.chars() {
        match character {
            '"' => result.push_str(r#"\""#),
            '\\' => result.push_str(r#"\\"#),
            '\n' => result.push_str(r#"\n"#),
            '\r' => result.push_str(r#"\r"#),
            '\t' => result.push_str(r#"\t"#),
            character => result.push(character),
        }
    }
    result
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    fn encode_roundtrip(msg: &Msg) -> Msg {
        decode(&encode(msg)).unwrap()
    }

    #[test]
    fn ping_encode_roundtrip() {
        assert!(matches!(encode_roundtrip(&Msg::Ping), Msg::Ping));
    }

    #[test]
    fn hello_uses_v2_envelope() {
        let encoded = encode(&Msg::Hello("world".into()));
        assert_eq!(encoded, r#"{"v":2,"hello":"world"}"#);
        assert!(matches!(decode(&encoded), Ok(Msg::Hello(value)) if value == "world"));
    }

    #[test]
    fn hello_roundtrip_escapes_json_values() {
        let message = Msg::Hello("say \"hello\"\n".into());
        assert!(matches!(encode_roundtrip(&message), Msg::Hello(value) if value == "say \"hello\"\n"));
    }
}
